{
  "name": "ARX5机器人机械臂",
  "name_en": "ARX5 robotic arm",
  "manufacturer": "",
  "description": "一款带夹爪的机器人机械臂，可按末端执行器位姿、工具中心点位姿或关节状态进行控制，适用于实验室中的抓取、搬运、定位和自动化操作研究。",
  "description_en": "A robotic manipulator with a gripper that can be controlled by end-effector pose, tool-center-point pose, or joint state, suitable for laboratory grasping, transfer, positioning, and automation experiments.",
  "tag_hints": [
    "robot manipulator",
    "gripper",
    "end-effector pose control",
    "TCP pose control",
    "joint-space control",
    "lab automation"
  ],
  "actions": [
    {
      "action_name": "auto-send_recv",
      "description": "发送原始消息并接收设备回复",
      "description_en": "Send a raw message and receive the device reply"
    },
    {
      "action_name": "auto-set_ee_pose",
      "description": "设置末端执行器位姿",
      "description_en": "Set the end-effector pose"
    },
    {
      "action_name": "auto-set_tcp_pose",
      "description": "设置工具中心点位姿",
      "description_en": "Set the tool center point pose"
    },
    {
      "action_name": "auto-reset_to_home",
      "description": "复位到初始位姿",
      "description_en": "Reset the robot to the home position"
    },
    {
      "action_name": "auto-set_to_damping",
      "description": "切换到阻尼模式",
      "description_en": "Switch the robot to damping mode"
    },
    {
      "action_name": "auto-set_gain",
      "description": "设置控制增益",
      "description_en": "Set the control gain"
    },
    {
      "action_name": "auto-get_state",
      "description": "获取设备状态",
      "description_en": "Get the device state"
    },
    {
      "action_name": "auto-get_gain",
      "description": "获取控制增益",
      "description_en": "Get the control gain"
    },
    {
      "action_name": "auto-timestamp",
      "description": "获取时间戳",
      "description_en": "Get the timestamp"
    },
    {
      "action_name": "auto-ee_pose",
      "description": "获取末端执行器位姿",
      "description_en": "Get the end-effector pose"
    },
    {
      "action_name": "auto-joint_pos",
      "description": "获取关节位置",
      "description_en": "Get the joint positions"
    },
    {
      "action_name": "auto-joint_vel",
      "description": "获取关节速度",
      "description_en": "Get the joint velocities"
    },
    {
      "action_name": "auto-joint_torque",
      "description": "获取关节力矩",
      "description_en": "Get the joint torques"
    },
    {
      "action_name": "auto-gripper_pos",
      "description": "获取夹爪位置",
      "description_en": "Get the gripper position"
    },
    {
      "action_name": "auto-gripper_vel",
      "description": "获取夹爪速度",
      "description_en": "Get the gripper velocity"
    },
    {
      "action_name": "auto-gripper_torque",
      "description": "获取夹爪力矩",
      "description_en": "Get the gripper torque"
    },
    {
      "action_name": "auto-tcp_pose",
      "description": "获取工具中心点位姿",
      "description_en": "Get the tool center point pose"
    }
  ]
}

